<script setup lang="ts">
import{computed,nextTick,onMounted,ref}from'vue';import{useRouter}from'vue-router';import{api,type ApiResponse,type UserProfile}from'@whaashop/shared';
const profile=ref<UserProfile>(),saving=ref(false),uploading=ref(false),message=ref(''),error=ref(''),fileInput=ref<HTMLInputElement>(),location=window.location,router=useRouter();
const initial=computed(()=>profile.value?.nickname?.slice(0,1).toUpperCase()||'用');const joined=computed(()=>profile.value?.createdAt?new Date(profile.value.createdAt).toLocaleDateString('zh-CN',{year:'numeric',month:'long'}):'');
onMounted(async()=>{const{data}=await api.get<ApiResponse<UserProfile>>('/shop/profile');profile.value=data.data;await nextTick();const menu=document.querySelectorAll('.profile-menu a'),quick=document.querySelectorAll('.quick-cards a');menu[3]?.addEventListener('click',()=>router.push('/addresses'));menu[4]?.addEventListener('click',()=>router.push('/my-reviews'));quick[2]?.addEventListener('click',()=>router.push('/my-reviews'))});
async function save(){if(!profile.value)return;saving.value=true;message.value='';error.value='';try{const{nickname,bio,gender,birthday}=profile.value;const{data}=await api.put<ApiResponse<UserProfile>>('/shop/profile',{nickname,bio,gender,birthday:birthday||null});profile.value=data.data;message.value='个人资料保存成功'}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function avatar(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;message.value='';error.value='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)){error.value='请选择 JPG、PNG 或 WebP 图片';return}if(file.size>10*1024*1024){error.value='头像图片不能超过 10MB';return}uploading.value=true;try{const form=new FormData();form.append('file',file);const{data}=await api.post<ApiResponse<UserProfile>>('/shop/profile/avatar',form);profile.value=data.data;window.dispatchEvent(new Event('profile-updated'));message.value='头像更新成功'}catch(e){error.value=(e as Error).message}finally{uploading.value=false;input.value=''}}
function cancel(){window.location.reload()}
</script>
<template><div class="profile-page"><div v-if="profile" class="container"><section class="profile-hero"><div class="profile-glow"></div><div class="avatar-wrap"><div class="avatar"><img v-if="profile.avatarUrl" :src="profile.avatarUrl" alt="用户头像"><span v-else>{{initial}}</span><button class="camera" :disabled="uploading" title="更换头像" @click="fileInput?.click()">{{uploading?'…':'⌁'}}</button></div><input ref="fileInput" class="file-input" type="file" accept="image/jpeg,image/png,image/webp" @change="avatar"><button class="upload-action" :disabled="uploading" @click="fileInput?.click()"><span>↑</span>{{uploading?'正在上传…':'更换头像'}}</button><small>支持 JPG、PNG、WebP，最大 10MB</small></div><div class="identity"><span class="member-tag">WhaaShop MEMBER</span><h1>{{profile.nickname}}</h1><p>@{{profile.username}}</p><div class="identity-meta"><span>橙心会员</span><i></i><span>{{joined}} 加入</span></div></div><div class="hero-stat"><b>个人主页</b><span>用喜欢的方式<br>记录你的商城生活</span></div></section><div class="profile-layout"><aside class="profile-menu"><div class="menu-title">个人中心</div><a class="active"><span>♙</span><div><b>个人资料</b><small>头像与基础信息</small></div></a><router-link to="/orders"><span>▤</span><div><b>我的订单</b><small>订单与售后进度</small></div></router-link><router-link to="/cart"><span>▱</span><div><b>我的购物车</b><small>待结算的商品</small></div></router-link><a><span>⌖</span><div><b>收货地址</b><small>管理常用地址</small></div></a><a><span>☆</span><div><b>我的评价</b><small>评价与追评记录</small></div></a></aside><main class="profile-content"><form class="profile-form" @submit.prevent="save"><div class="form-heading"><div><span>PROFILE SETTINGS</span><h2>编辑个人资料</h2><p>完善资料，让我们更懂你的偏好</p></div><div class="completion"><b>80%</b><small>资料完整度</small></div></div><div class="form-grid"><label><span>昵称</span><input v-model="profile.nickname" maxlength="50" required placeholder="请输入昵称"><small>商城中展示的名称</small></label><label><span>用户名</span><input :value="profile.username" disabled><small>用户名不可修改</small></label><label class="full"><span>个人简介</span><textarea v-model="profile.bio" maxlength="300" rows="5" placeholder="介绍一下自己，分享你的兴趣和生活方式…"></textarea><small class="counter">{{profile.bio?.length||0}} / 300</small></label><label><span>性别</span><select v-model="profile.gender"><option value="UNSPECIFIED">不公开</option><option value="MALE">男</option><option value="FEMALE">女</option></select></label><label><span>生日</span><input v-model="profile.birthday" type="date"></label></div><div v-if="message||error" :class="['notice',{error}]">{{error||message}}</div><div class="form-actions"><button type="button" class="cancel" @click="location.reload()">取消修改</button><button class="save" :disabled="saving"><span>✓</span>{{saving?'正在保存…':'保存修改'}}</button></div></form><section class="quick-cards"><router-link to="/orders"><i>▤</i><div><b>我的订单</b><span>查看全部订单状态</span></div><strong>→</strong></router-link><router-link to="/cart"><i>▱</i><div><b>购物车</b><span>继续完成选购</span></div><strong>→</strong></router-link><a><i>☆</i><div><b>评价中心</b><span>分享真实购物体验</span></div><strong>→</strong></a></section></main></div></div></div></template>
