order-color:#fb923c;box-shadow:0 0 0 3px #ffedd5}.form-grid input:disabled{background:#f8f4f1;color:#a88772}.form-grid label>small{display:block;margin-top:5px;font-size:10px;color:#a88772}.form-grid .full{grid-column:1/-1;position:relative}.counter{text-align:right}.notice{margin-top:18px;padding:11px 14px;border-radius:9px;background:#f0fdf4;color:#15803d}.notice.error{background:#fef2f2;color:#dc2626}.form-actions{display:flex;justify-content:flex-end;gap:10px;border-top:1px solid #f3e7df;margin-top:25px;padding-top:22px}.form-actions button{padding:11px 21px;border-radius:99px;font-weight:800;cursor:pointer}.cancel{border:1px solid #ead8ca;background:#fff;color:#765744}.save{border:0;background:#f97316;color:#fff;box-shadow:0 8px 18px #f9731633}.save span{margin-right:6px}.quick-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-top:15px}.quick-cards a{display:grid;grid-template-columns:42px 1fr auto;gap:10px;align-items:center;padding:17px;border-radius:14px;text-decoration:none;color:#624737}.quick-cards i{width:40px;height:40px;display:grid;place-items:center;border-radius:10px;background:#fff2e6;color:#ea580c;font-style:normal}.quick-cards b,.quick-cards span{display:block}.quick-cards span{font-size:10px;color:#a88772;margin-top:4px}.quick-cards strong{color:#f97316}@media(max-width:850px){.profile-hero{grid-template-columns:160px 1fr;padding:28px}.hero-stat{display:none}.profile-layout{grid-template-columns:1fr}.profile-menu{display:grid;grid-template-columns:repeat(3,1fr)}.menu-title{display:none}.profile-menu a{justify-content:center}.profile-menu a div{display:none}}@media(max-width:600px){.profile-hero{grid-template-columns:1fr;text-align:center}.identity-meta{justify-content:center}.form-grid{grid-template-columns:1fr}.form-grid .full{grid-column:auto}.quick-cards{grid-template-columns:1fr}.profile-menu{grid-template-columns:repeat(5,1fr)}.profile-menu a{padding:7px}.profile-form{padding:20px}.form-heading{align-items:flex-start}.c